insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('urania-steanwarte', 'Urania Steanwarte', '', '', '', '', 'Urania-Sternwarte', '[{"kategorie": "allg.", "text": "\"historische öffentliche Sternwarte in Wien, die sich im Gebäude der [[Urania]] befindet\""}, {"kategorie": "", "text": "Die Urania-Sternwarte wurde 1910 von [[Kaiser]] Franz Joseph I. als Teil des Gebäudekomplexes der [[Wiener]] Urania eröffnet und ist seitdem ein wichtiger Ort für die astronomische Bildung und Forschung in Wien"}, {"kategorie": "", "text": "Neben der Beobachtung von Himmelskörpern dient die Urania-Sternwarte auch als Ort für wissenschaftliche Vorträge und Führungen, die das Interesse an der Astronomie fördern sollen. Sie ist ein bedeutendes kulturelles Erbe der Stadt Wien und weiterhin ein beliebtes Ziel für Wissenschaftsinteressierte und Touristen."}]'::jsonb, ''),
  ('haus-mit-goidana-kuppae', 'Haus mit goidana Kuppä', '', '', '', '', 'Haus mit goldener Kuppel', '[{"kategorie": "hist.", "text": "markantes Gebäude an der [[Linken]] Wienzeile 40 im 6. Wiener Gemeindebezirk ([[Mariahilf]]), auch bekannt als Medienhaus oder Köhlerhaus"}, {"kategorie": "", "text": "Es wurde von dem berühmten Architekten Otto Wagner entworfen und zwischen 1898 und 1899 als Teil seiner Wohnhausserie entlang der Wienzeile errichtet"}, {"kategorie": "", "text": "Das herausragende Merkmal des Gebäudes ist die prächtige, vergoldete Kuppel, die dem Haus seinen umgangssprachlichen Namen verleiht. Diese Kuppel und die reich verzierte Fassade mit floralen Ornamenten sind typische Elemente des [[Wiener]] Jugendstils. Das Haus steht neben dem [[Majolika-Haus]] und dem [[Wienzeilenhaus]] und bildet mit ihnen zusammen eine Einheit von Gebäuden, die den Jugendstil in Wien repräsentieren."}]'::jsonb, ''),
  ('wiina-urania', 'Wiina Urania', '', '', '', '', 'Wiener Urania', '[{"kategorie": "hist.", "text": "\"bedeutendes öffentliches Gebäude in Wien, das als Bildungs- und Kulturzentrum dient und ein markantes Beispiel für die Architektur der Wiener Moderne ist\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk (Innere Stadt), an der Mündung des [[Wienflusses]] in den [[Donaukanal]], und ist heute Volksbildungshaus samt Sternwarte, Kino und Café"}, {"kategorie": "", "text": "Das im Jugendstil errichtete Gebäude  wurde 1910 eröffnet und beinhaltet eines der ältesten Planetarien der Welt, die im Kuppelbau untergebracht ist"}]'::jsonb, ''),
  ('wiina-jugendsdueue', 'Wiina Jugendsdüü', '', '', '', '', 'Wiener Jugendstil', '[{"kategorie": "hist.", "text": "\"Kunst- und Architekturbewegung, die sich um die Wende vom 19. zum 20. Jahrhundert in Wien entwickelte\" (auch [[Sezessionsstil]] genannt)"}, {"kategorie": "", "text": "Diese Bewegung ist Teil des größeren Jugendstil-Stils, der in verschiedenen europäischen Ländern als Art Nouveau (Frankreich und Belgien) oder Modern Style (England) bekannt ist"}, {"kategorie": "", "text": "Der Wiener Jugendstil zeichnet sich durch eine Kombination aus innovativem Design, künstlerischer Ausdruckskraft und einer Abkehr von traditionellen, historistischen Stilrichtungen aus"}]'::jsonb, ''),
  ('d-insl', 'd''Insl', '', '', '', '', 'Die Insel', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"die [[Wiener]] Donauinsel\""}, {"kategorie": "", "text": "Sie ist eine künstlich angelegte Insel in Wien, die sich über eine Länge von etwa 21 Kilometern zwischen der [[Donau]] und der [[Neuen]] Donau erstreckt"}, {"kategorie": "", "text": "\"Die Insel\" liegt im 21. und 22. Bezirk Wiens ([[Floridsdorf]] bzw. [[Donaustadt]]) und ist ein bedeutendes Naherholungsgebiet sowie ein wichtiger Teil des Hochwasserschutzsystems der Stadt"}, {"kategorie": "", "text": "Berühmtheit erlangte die Donauinsel vor allem auch durch das alljährlich stattfindende [[Donauinselfest]]"}]'::jsonb, ''),
  ('gruena-prooda', 'Grüna Prooda', '', '', '', '', 'Grüner Prater', '[{"kategorie": "allg.", "text": "weitläufiges Erholungsgebiet im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), das den größten Teil des [[Praters]], eines der bekanntesten und bedeutendsten Parks in Wien, bildet"}, {"kategorie": "", "text": "Der Grüne Prater umfasst eine ausgedehnte Parklandschaft, die von Wiesen, Wäldern, Teichen und Wegen geprägt ist und sich ideal für vielfältige Freizeitaktivitäten eignet"}, {"kategorie": "", "text": "Eine der zentralen Achsen des Grünen Praters ist die [[Prater]] Hauptallee, eine 4,5 Kilometer lange, schnurgerade Allee, die von Kastanienbäumen gesäumt wird. Sie beginnt am [[Praterstern]] und führt bis zum [[Lusthaus]], einem historischen Gebäude am südlichen Ende des Parks"}, {"kategorie": "", "text": "Ein weiteres Highlight ist die [[Jesuitenwiese]], eine große Freifläche, die oft für Veranstaltungen und Feste genutzt wird."}]'::jsonb, ''),
  ('messe-wiin', 'Messe Wiin', '', '', '', '', 'Messe Wien', '[{"kategorie": "allg.", "text": "eines der größten und modernsten Messe- und Kongresszentren in Österreich, gelegen im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), auch bekannt als [[Wiener Messegelände]] bzw. [[Wiener Messe]]"}, {"kategorie": "", "text": "Sie befindet sich in unmittelbarer Nähe zum [[Wiener]] Prater und zum [[Ernst-Happel-Stadion]] und ist ein zentraler Ort für internationale Messen, Kongresse, Ausstellungen und Veranstaltungen in Wien"}, {"kategorie": "", "text": "Schon im 19. Jahrhundert fanden im Wiener Prater und auf dem heutigen Messegelände verschiedene große Ausstellungen statt, die Wien zu einem wichtigen Messestandort machten. Dazu gehörte die Weltausstellung 1873, die im Prater stattfand und Wien international bekannt machte"}, {"kategorie": "", "text": "Die Messe Wien besteht aus mehreren modernen Messehallen, einem Kongresszentrum und weiteren Veranstaltungsräumen, die auf einem großzügigen Gelände über eine Fläche von ca. 60.000 m² verteilt sind."}]'::jsonb, ''),
  ('galopprennbaun-freidenau', 'Galopprennbaun Freidenau', '', '', '', '', 'Galopprennbahn Freudenau', '[{"kategorie": "hist.", "text": "historisches Juwel im 2. Wiener Gemeindebezirk (Leopoldstadt) in der Nähe des [[Lusthauses]] im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]). 2. Die Rennbahn wurde 1839 eröffnet, das erste Österreichische Derby fand 1868 statt, und beim Derby 1913 waren gar 40.000 Besucher anwesend. 3. Nach einem Großbrand und den beiden Weltkriegen versank die Galopprennbahn Freudenau in einen Dornröschenschlaf, aus dem sie bis heute nicht wirklich erwacht ist. Unberührt vom hektischen Treiben der Stadt erinnert sie den Spaziergänger inmitten grüner Auen an längst vergangene Zeiten. Heute ist die Freudenau mit der berühmten Kaiserloge ein moderner Veranstaltungsort für Events aller Art."}]'::jsonb, ''),
  ('prooda-hauptallee', 'Prooda Hauptallee', '', '', '', '', 'Prater Hauptallee', '[{"kategorie": "hist.", "text": "\"Im 16. Jahrhundert angelegte, schnurgerade, 4,5km lange Baumallee mit Fußgänerpromenaden, Rad- und Reitwegen im [[Grünen]] Prater\""}, {"kategorie": "", "text": "Sie führt vom [[Praterstern]] (Verkehrsknotenpunkt samt U-Bahn-Station) bis zum [[Lusthaus]] und liegt im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "hist.", "text": "[[Nobelprater]] (Im ausgehenden 19. Jahrhundert war die Prater Hauptallee DIE Ausgehmeile Wiens schlechthin, an der Adel und Großbürgertum flanierten, um sich der Öffentlichkeit zu präsentieren, weshalb das Gebiet entlang der Prater Hauptallee schon bald als \"Nobelprater\" bezeichnet wurde. Von den akkurat in zwei Reihen platzierten modernen Eisensesseln an der Allee, die von sogenannten [[Sesselfrauen]] gegen eine Mietgebühr zur Verfügung gestellt wurden, konnte man das allgemeine gesellschaftliche Geschehen hervorragend beobachten und auch vorzüglich kommentieren)."}]'::jsonb, ''),
  ('a-faesche-hex', 'a fäsche Hex', '', '', '', '', 'eine fesche Hex', '[{"kategorie": "wörtlich", "text": "\"ein hübsches, attraktives Mädchen\""}, {"kategorie": "", "text": "eine entzückende, gutaussehende Frau"}, {"kategorie": "", "text": "eine echte Augenweide"}]'::jsonb, ''),
  ('a-baeaese-hex', 'a bääse Hex', '', '', '', '', 'eine böse Hex', '[{"kategorie": "wörtlich", "text": "\"ein streitbares Mädchen\""}, {"kategorie": "", "text": "eine boshafte Frau"}, {"kategorie": "", "text": "eine hinterhältige Göre"}]'::jsonb, ''),
  ('zu-fronleichnaum-haums-in-vagoidetn-himmae-bei-da-prozession-mit-weisse-handschuach-troong', 'Zu Fronleichnaum haums in vagoidetn Himmä bei da Prozession mit weisse Handschuach troong!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Zu Fronleichnam haben sie den vergoldeten Himmel bei der Prozession mit weißen Handschuhen getragen!', '[{"kategorie": "wörtlich", "text": "\"Bei der Fronleichnamsprozession wurde der vergoldete Dachhimmel wie jedes Jahr mit weißen Handschuhen getragen!\"  2. Der goldene Dachhimmel wurde bei der Fronleichnamsprozession von Himmelträgern mit weißen Handschuhen getragen!  3. Die Männer mit den weißen Handschuhen trugen den prunkvollen Dachhimmel bei der Fronleichnamsprozession - so wie jedes Jahr!"}]'::jsonb, ''),
  ('de-marii-hiiblaadln', 'de Marii hiiblaadln', '', '', '', '', 'die Marie hinblatteln', '[{"kategorie": "wörtlich", "text": "\"die Geldscheine hinblättern\" (vom mittelhochdeutschen \"bleteren\"=\"Blatt für Blatt umwenden\")"}, {"kategorie": "", "text": "die Geldscheine auf den Tisch blättern"}, {"kategorie": "", "text": "die Geldscheine auf den Tisch legen"}]'::jsonb, ''),
  ('auf-wos-hinauf', 'Auf wos hinauf?', '', '', '', '', 'Auf was hinauf', '[{"kategorie": "", "text": "Aus welchem Grund?  2. Mit welcher Begründung?  3. Aus welchem Beweggrund?"}]'::jsonb, 'Auf wos hinauf tua I ma des au?'),
  ('auf-des-hinauf', 'auf des hinauf', '', '', '', '', 'auf das hinauf!', '[{"kategorie": "wörtlich", "text": "\"als Reaktion darauf\""}, {"kategorie": "allg.", "text": "als Folge davon"}, {"kategorie": "", "text": "im Anschluss daran"}]'::jsonb, ''),
  ('des-hiifollade-haum', 'des Hiifollade haum', '', '', '', '', 'das Hinfallerte haben', '[{"kategorie": "wörtlich", "text": "\"die Fallkrankheit haben\" (in Anspielung darauf, dass Epilepsiekranke oft unkontrolliert zu Boden fallen)"}, {"kategorie": "med.", "text": "an Epilepsie leiden, unter epileptischen Anfällen leiden, an Fallsucht leiden"}, {"kategorie": "allg.", "text": "\"sturzanfällig sein\";  auf wackeligen Beinen stehen, stolperanfällig sein, \"leicht zu Sturz kommen\""}]'::jsonb, ''),
  ('hint-und-vuan', 'hint und vuan', '', '', '', '', 'hint und vorn', '[{"kategorie": "wörtlich", "text": "\"hinten und vorne\""}, {"kategorie": "", "text": "von vorne bis hinten"}]'::jsonb, ''),
  ('mia-geeds-hint-und-vuan-ned-zsaumm', 'Mia geeds hint und vuan ned zsaumm!', '', '', '', '', 'Mir geht es vorne und hinten nicht zusammen!', '[{"kategorie": "", "text": "Ich weiß weder ein noch aus!  2. Ich habe nicht mehr genug zum Leben!  3. Ich bin in finanzieller Not!"}]'::jsonb, ''),
  ('wem-ollas-hint-und-vuan-eineschiam', 'wem ollas hint und vuan eineschiam', '', '', '', '', 'jemandem alles hinten und vorne reinschieben', '[{"kategorie": "", "text": "jemanden maßlos verwöhnen, jemanden \"von vorne bis hinten\" bedienen"}, {"kategorie": "", "text": "jemandem ungefragt jeden Wunsch von den Augen ablesen"}]'::jsonb, ''),
  ('wem-hint-und-vuan-bescheissn', 'wem hint und vuan bescheissn', '', '', '', '', 'jemanden hinten und vorne bescheißen', '[{"kategorie": "", "text": "jemanden von vorne bis hinten bescheißen"}, {"kategorie": "", "text": "jemanden nach Strich und Faden betrügen"}]'::jsonb, ''),
  ('bei-dera-is-hint-und-vuan-nix-drau', 'Bei dera is hint und vuan nix drau!', '', '', '', '', 'Bei der ist hinten und vorne nichts dran!', '[{"kategorie": "", "text": "Die ist weder von vorne noch von hinten schön anzuschauen!  2. Weibliche Formen suchst du bei ihr von vorne bis hinten vergeblich!"}]'::jsonb, ''),
  ('dem-zeig-i-den-hintan', 'Dem zeig I den Hintan!', '', '', '', '', 'Dem zeige ich den Hintern!', '[{"kategorie": "", "text": "Den lasse ich brutal abblitzen!  2. Der kann mich mal!  3. Dem gebe ich die [[Gurken]]!"}]'::jsonb, ''),
  ('duachs-hintatiarl-kumma', 'duachs Hintatiarl kumma', '', '', '', '', 'durchs Hintertürl kommen', '[{"kategorie": "wörtlich", "text": "durchs Hintertürchen kommen, sich jemandem heimlich von hinten nähern"}, {"kategorie": "", "text": "etwas auf unlautere Weise zu erreichen versuchen, unredlich vorgehen"}, {"kategorie": "", "text": "hinterhältig agieren, sich einschleichen"}]'::jsonb, ''),
  ('hintnooch-waass-ma-ollas-bessa', 'Hintnooch waaß ma ollas bessa!', '', '', '', '', 'Hintnach weiß man alles besser', '[{"kategorie": "", "text": "Im Nachhinein ist man immer klüger!  2. Im Nachhinein weiß man immer alles besser!"}]'::jsonb, ''),
  ('hintnooch-is-a-jeda-a-prophet', 'Hintnooch is a jeda a Prophet!', '', '', '', '', 'Hintnach ist ein jeder ein Prophet', '[{"kategorie": "", "text": "Im Nachhinein ist man immer klüger!  2. Im Nachhinein weiß man immer alles besser!"}]'::jsonb, ''),
  ('es-is-zum-hiiwean', 'Es is zum Hiiwean!', '', '', '', '', 'Es ist zum Hinwerden!', '[{"kategorie": "", "text": "Es ist zum Totlachen!  2. Es ist zum Totärgern!"}]'::jsonb, ''),
  ('i-waass-ned-wo-i-ihna-hiituan-soi', 'I waaß ned, wo I Ihna hiituan soi!', '', '', '', '', 'Ich weiß nicht, wo ich Sie hintun soll!', '[{"kategorie": "", "text": "Ich kann Ihr Gesicht im Moment nicht zuordnen!  2. Ich kenne Ihr Gesicht, weiß aber nicht mehr, von wo!"}]'::jsonb, ''),
  ('bochanes-hian', 'Bochanes Hian', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gebackenes Hirn', '[{"kategorie": "Gastronomie", "text": "gebackenes Schweinshirn, paniertes Schweinshirn (schmackhaftes Innereiengericht)"}]'::jsonb, ''),
  ('des-kaunnst-da-aufs-hian-pickn', 'Des kaunnst da aufs Hian pickn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das kannst du dir aufs Hirn picken!', '[{"kategorie": "wörtlich", "text": "\"Das kannst du dir an den Hut stecken!\"  2. Das kannst du getrost behalten!  3. [[Das]] kannst du dir auf den Nabel picken!  4. Das gehört jetzt dir und deiner Sammlung!  5. [[Das]] kannst du dir in den Arsch schieben!  6. [[Das]] kannst du dir einführen!"}]'::jsonb, ''),
  ('do-steed-ma-s-hian', 'Do steed ma s''Hian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da steht mir das Hirn!', '[{"kategorie": "wörtlich", "text": "Da steh ich auf der Leitung!  2. Da weiß ich nicht mehr weiter!  3. Ich steh total auf dem Schlauch!  4. Ich check gar nichts mehr!"}]'::jsonb, ''),
  ('dea-hods-hian-in-da-toschn', 'Dea hods Hian in da Toschn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der hat das Hirn in der Tasche!', '[{"kategorie": "wörtlich", "text": "\"Der trägt das Hirn in der Hosentasche - und die ist leer!\"  2. Der hat sein Gehirn wohl zu Hause vergessen!  3. Der trägt das Hirn in der Tasche - sein Kopf ist nur zum Haaretragen da!"}]'::jsonb, ''),
  ('waunn-dea-an-reengwuam-schlickt-hoda-mea-hian-im-bauch-wia-in-schaedl', 'Waunn dea an Reengwuam schlickt, hoda mea Hian im Bauch wia in Schädl!', '', '', '', 'Echte Wiener Schmähperlen', 'Wenn der einen Regenwurm schluckt, hat er mehr Hirn im Bauch als im Schädel!', '[{"kategorie": "wörtlich", "text": "\"Wenn der einen Regenwurm isst, landet mehr Verstand in seinem Magen als er im Kopf hat!\"  2. (scherzhaft für): \"Wenn der einen Regenwurm verschlingt, hat er postwendend mehr Grips im Bauch als im Hirn!  3. Wenn der einen Regenwurm verschluckt, besitzt er mehr Intellekt im Magen als im Kopf!"}]'::jsonb, ''),
  ('hoid-in-kopf-schiif-damids-hian-zsaummrinnd', 'Hoid in Kopf schiif, damids Hian zsaummrinnd!', '', '', '', 'Echte Wiener Schmähperlen', 'Halt den Kopf schief, damit das Hirn zusammenrinnt!', '[{"kategorie": "wörtlich, scherzhaft für", "text": "Kipp den Kopf, damit die Weisheit in deinem Hirn zusammenlaufen kann!“  2. Leg den Kopf schräg, damit die paar Gehirnzellen in deinem Schädel zusammenwachsen!  3. Leg den Kopf zur Seite, vielleicht rutscht die Intelligenz dann an den richtigen Platz!"}]'::jsonb, ''),
  ('si-de-guagl-oeoen', 'si de Guagl öön', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich die Gurgel ölen', '[{"kategorie": "wörtlich", "text": "\"sich die Kehle schmieren\""}, {"kategorie": "scherzhaft für", "text": "\"sich den Rachen spülen\""}, {"kategorie": "", "text": "sich Alkoholisches [[in]] die Venen hauen"}, {"kategorie": "", "text": "sich einen hinter die Binde kippen"}, {"kategorie": "", "text": "sich was Hochprozentiges [[in]] die Figur stoßen"}]'::jsonb, ''),
  ('de-is-so-a-hianchristl-dass-in-kochtopf-min-nochttopf-vawechsld', 'De is so a Hianchristl, dass in Kochtopf min Nochttopf vawechsld!', '', '', '', '', 'Die ist so ein Hirnchristl, dass sie den Kochtopf mit dem Nachttopf verwechselt!', '[{"kategorie": "wörtlich", "text": "\"Die ist ein solcher Dummkopf von Gottes Gnaden, dass sie den Kochtopf mit dem Nachttopf verwechselt!\" 2. (fig.) Die ist an Dummheit nicht zu überbieten!  3. Die ist ein Vollpfosten vor dem Herren!  4. Die ist dumm wie Bohnenstroh!"}]'::jsonb, ''),
  ('du-hianglotzada-dillo', 'Du hianglotzada Dillo!', '', '', '', '', 'Du hirnglatzerter Dillo!', '[{"kategorie": "wörtlich", "text": "\"Du hirnverbrannter Hohlkopf!\"  2. \"Du stirnglatzerter Vollpfosten!\"  3. Du Schüttler mit Stirnglatze!"}]'::jsonb, ''),
  ('den-hianproella-sauf-i-nimma-von-dem-brummd-da-a-wochn-laung-da-schaeaedl', 'Den Hianprölla sauf I nimma - von dem brummd da a Wochn laung da Schäädl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Diesen Hirnpreller sauf ich nimmer - von dem brummt dir eine Woche lang der Schädel!', '[{"kategorie": "wörtlich", "text": "\"Diesen billigen, gepanschten Wein trink ich nimmer - von dem bekommst du nur Kopfweh!\"  2. \"Den Fusel rühr ich nimmer an – davon platzt dir der Schädel!\"  3. \"Diesen Billigsdorfer sauf ich nimmer – davon brummt dir eine Woche lang der Schädel!\""}]'::jsonb, ''),
  ('von-dem-hecknklaescha-gestan-hob-i-heit-a-ausgwochsane-hianproellung', 'Von dem Hecknkläscha gestan hob I heit a ausgwochsane Hianpröllung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Von dem Heckenklescher gestern hab ich heut eine ausgewachsene Hirnprellung!', '[{"kategorie": "wörtlich", "text": "\"Von dem Fusel gestern hab ich heut eine ausgewachsene Hirnprellung!\"  2. \"Von dem billigen, gepanschten Wein hab ich heute einen regelrechten Brummschädel!\"  3. \"Der Billigwein von gestern hat mir heute einen mordstrumm Kater beschert!\""}]'::jsonb, ''),
  ('a-leewaproella-is-wia-russiches-roulette-ma-waass-nii-ob-ma-gwinnd-oda-draufgeed', 'A Leewaprölla is wia russiches Roulette - ma waass nii, ob ma gwinnd oda draufgeed!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Leberpreller ist wie russisches Roulette - man weiß nie, ob man gewinnt oder draufgeht!', '[{"kategorie": "wörtlich", "text": "\"Ein leberschädigender Billigwein ist wie russisches Roulette - man weiß nie, ob man gewinnt oder draufgeht!\"  2. Billigwein ist wie russisches Roulette – nur dass die Kugel brennt und nach Trauben riecht!  3. Bei einem Leberpreller gibt''s nur zwei Optionen: Vollrausch oder Notaufnahme!"}]'::jsonb, ''),
  ('si-de-hianschaukl-geem', 'si de Hianschaukl geem', '', '', '', '', 'sich die Hirnschaukel geben', '[{"kategorie": "", "text": "fernsehen"}, {"kategorie": "", "text": "fernschauen"}]'::jsonb, ''),
  ('dea-glaubd-nua-waeura-an-groossn-hoowae-hod-deafan-iwaroi-eineschiam', 'Dea glaubd, nua wäura an groossn Hoowä hod, deafan iwaroi eineschiam!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der glaubt, nur weil er einen großen Hobel hat, darf er ihn überall reinschieben!', '[{"kategorie": "wörtlich", "text": "\"Der glaubt, nur weil er einen großen Penis hat, darf er ihn überall reinschieben!\"  2. Der denkt, nur weil er gut bestückt ist, kriegt er jede Frau auf dieser Welt!  3. Der meint, mit seinem Riesenteil kann er jede haben!"}]'::jsonb, ''),
  ('du-kaunnst-ma-in-hoowae-ausbloosn', 'Du kaunnst ma in Hoowä ausbloosn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Du kannst mir den Hobel ausblasen!', '[{"kategorie": "wörtlich", "text": "\"Du kannst mir den Buckel runterrutschen!\"  2. Du kannst mich gern haben!  3. Du kannst mich mal kreuzweise!\" (Zur Erklärung: Das Reinigen [\"Ausblasen\"] des Hobels war eine höchst unangenehme Aufgabe, welche der Tischlermeister stets den Lehrlingen überließ, da einem \"beim Hobelausblasen\" ständig Späne ins Auge flogen)"}]'::jsonb, ''),
  ('si-zu-wem-hockn', 'si zu wem hockn', '', '', '', '', 'sich zu jemandem hocken', '[{"kategorie": "", "text": "sich zu jemandem setzen"}, {"kategorie": "", "text": "sich neben jemandem hinsetzen"}]'::jsonb, ''),
  ('an-hockn-haum', 'an hockn haum', '', '', '', '', 'einen hocken haben', '[{"kategorie": "", "text": "einen sitzen haben"}, {"kategorie": "", "text": "betrunken sein"}]'::jsonb, ''),
