  ('si-auschiidn', 'si auschiidn', '', '', '', 'Grundwortschatz Wienerisch', 'sich anschütten', '[{"kategorie": "wörtlich", "text": "\"sich nass machen\" (vom mittelhochdeutschen \"anschüten\"=\"das Erdreich aufschwemmen\")"}, {"kategorie": "allg.", "text": "sich betrinken, sich einen Rausch antrinken, sich andudeln"}, {"kategorie": "fig.", "text": "sich anpatzen, sich selbst besudeln, ins Fettnäpfchen treten, sich bis auf die Knochen blamieren"}, {"kategorie": "Fußballerjargon, Tormann", "text": "sich stümperhaft anstellen, sich zum Affen machen, sich zum Deppen machen, [[ein]] Eiertor bekommen (sich stümperhaft anstellen und deshalb ein Tor erhalten)"}]'::jsonb, 'Da Gooli schiid si au und faungd kan anzign Boin!'),
  ('maunche-saufn-aus-freid-aundare-aus-kumma-i-schiid-mi-aafoch-nuar-au', 'Maunche saufn aus Freid, aundare aus Kumma - I schiid mi aafoch nuar au!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Manche saufen aus Freude, andere aus Kummer – ich schütte mich einfach nur an!', '[{"kategorie": "wörtlich", "text": "\"Manche trinken aus Freude, andere aus Kummer – ich trinke mir einfach nur einen Rausch an!\"  2. Die einen saufen, weil sie feiern – die anderen, weil sie trauern. Ich sauf sowieso!  3. Ich sauf nicht zum Spaß und auch nicht aus Kummer. Ich sauf, weil ich’s kann. Alles andere is’ Nebensache!"}]'::jsonb, 'si auschiidn'),
  ('si-schiidn-eam-au-obwoi-ea-goa-nix-dafia-kaunn', 'Si schiidn eam au, obwoi ea goa nix dafia kaunn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sie schütten ihn an, obwohl er gar nichts dafür kann!', '[{"kategorie": "wörtlich", "text": "\"Sie schwärzen ihn an, obwohl ihn gar keine Schuld trifft!\"  2. Sie hängen ihm etwas an, obwohl er nichts dafür kann!  3. Sie stellen ihn bloß, obwohl er keine Schuld hat!"}]'::jsonb, ''),
  ('tua-mi-ned-min-tee-auschiidn', 'Tua mi ned min Tee auschiidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Tu mich nicht mit Tee anschütten!', '[{"kategorie": "wörtlich", "text": "\"Erspare mir dein sinnloses Gequatsche!\"  2. Erzähl mir keinen Unsinn!  3. Spar dir dein hohles Geschwätz!  4. Komm mir nicht mit deinem leeren Gelaber!"}]'::jsonb, ''),
  ('aeaga-ois-dea-kaunnst-di-ned-auschiidn', 'Äaga ois dea kaunnst di ned auschiidn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ärger als der kannst du dicht nicht anschütten!', '[{"kategorie": "wörtlich", "text": "\"Ärger als er kann man sich nicht blamieren!\"  2. Übler kannst du dich nicht bloßstellen!  3. Schlimmer kannst du dich selbst nicht bloßstellen!"}]'::jsonb, 'si auschiidn'),
  ('da-gooli-hod-si-komplett-augschitt', 'Da Gooli hod si komplett augschitt!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Goalie hat sich komplett angeschüttet!', '[{"kategorie": "wörtlich", "text": "\"Der Tormann hat sich bis auf die Knochen blamiert!\"  2. Der Torwart hat sich voll zum Affen gemacht!  3. Der Goalie hat sich einen kapitalen Aussetzer geleistet!  4. Der Torwart hat sich selbst abgeschossen!"}]'::jsonb, 'si auschiidn'),
  ('bist-augschitt-du-oaschgrammae', 'Bist augschitt, du Oaschgrammä?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Bist du angeschüttet, du Arschgrammel?', '[{"kategorie": "wörtlich, in Bezug auf weibliche Personen, derb abwertend", "text": "Bist du noch ganz dicht, verdammte Giftspritze?  2. Hast du sie noch alle, du beschissenes Arschweib?  3. Bist du komplett durchgeknallt, du liederliche Lästerschwester?"}]'::jsonb, ''),
  ('si-auschbeibm', 'si auschbeibm', '', '', '', '', 'sich anspeiben', '[{"kategorie": "wörtlich", "text": "\"sich anspeien\""}, {"kategorie": "", "text": "erbrechen, sich übergeben, [[reihern]]"}, {"kategorie": "", "text": "sich mit Erbrochenem besudeln, beklecksen"}, {"kategorie": "", "text": "sich vor etwas ekeln, bei etwas Brechreiz empfinden, [[recken]]"}]'::jsonb, ''),
  ('i-speib-mi-au', 'I speib mi au!', '', '', '', '', 'Ich speib mich an!', '[{"kategorie": "", "text": "Ich muss mich gleich übergeben!  2. Das ekelt mich an!  3. Mir graut davor!"}]'::jsonb, ''),
  ('eam-ausetzn', 'eam ausetzn', '', '', '', '', 'ihn ansetzen', '[{"kategorie": "wörtlich", "text": "\"den Penis ansetzen\""}, {"kategorie": "", "text": "eine Frau mit dem Penis penetrieren"}, {"kategorie": "", "text": "eine Frau schwängern, einer Frau ein Kind machen"}]'::jsonb, ''),
  ('loss-mi-ausn-kraut', 'Loss mi ausn Kraut!', '', '', '', '', 'Lass mich aus dem Kraut!', '[{"kategorie": "", "text": "Lass mich in Ruhe!  2. Lass mich in Frieden!  3. [[Loss]] mi auglaand!"}]'::jsonb, ''),
  ('mit-wem-auhaengan', 'mit wem auhängan', '', '', '', '', 'mit jemandem anhängen', '[{"kategorie": "", "text": "sich mit jemandem anlegen"}, {"kategorie": "", "text": "Streit suchen mit jemandem"}]'::jsonb, ''),
  ('dea-woa-so-augsuudad-dass-sei-gsichd-ausgschaud-hod-wiara-granticha-paradeisa', 'Dea woa so augsuudad, dass sei Gsichd ausgschaud hod wiara granticha Paradeisa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der war so angesudert, dass sein Gesicht ausgeschaut hat wie ein grantiger Paradeiser!', '[{"kategorie": "wörtlich", "text": "\"Er war so verärgert und voller Groll, dass sein Gesicht die Form einer zornigen, verschrumpelten Tomate angenommen hatte!\"  2. Sein Groll war so heftig, dass sich seine Züge sich zu einer einzigen, grimmigen Grimasse verzogen hatten!  3. Er war dermaßen angefressen, dass er dreing’schaut hat wie ein Arsch, der sich selber nicht riechen kann!\""}]'::jsonb, ''),
  ('dea-schaud-so-augsuudad-wiara-oasch-dea-si-soeoewa-ned-riachn-kau', 'Dea schaud so augsuudad wiara Oasch, dea si sööwa ned riachn kau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schaut so angesudert wie ein Arsch, der sich selber nicht riechen kann!', '[{"kategorie": "wörtlich", "text": "\"Der schaut so stinksauer aus der Wäsche wie ein Arsch, dem sein eigener Geruch zu widerwärtig ist!\"  2. Der zieht eine Fresse wie ein Arsch, dem die ganze Welt stinkt – inklusive er selber!  3. Sein Blick ist so verbittert, dass er saure Milch zum Gerinnen bringen könnte!"}]'::jsonb, ''),
  ('dea-mochd-a-augsuudads-gschau-wia-waunn-eam-de-gaass-augschissn-haed', 'Dea mochd a augsuudads Gschau, wia waunn eam de Gaass augschissn häd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der macht ein angesudertes Geschau, wie wenn ihn die Geiß angeschissen hätte!', '[{"kategorie": "wörtlich", "text": "\"Der schaut so angefressen, wie wenn er einen Haufen Ziegenkot im Gesicht kleben hätte!\"  2. Der schaut so stinksauer aus der Wäsche wie ein Arsch, der sich selber nicht riechen kann!  3. Sein Blick ist so verbittert, dass er saure Milch zum Gerinnen bringen könnte!"}]'::jsonb, ''),
  ('an-fetzn-hoda-no-ned-oba-augschdochn-isa', 'An Fetzn hoda no ned, oba augschdochn isa!', '', '', '', '', 'Einen Fetzen hat er noch nicht, aber angestochen ist er!', '[{"kategorie": "", "text": "Einen Rausch hat er noch nicht, aber leicht beschwipst ist er!  2. Einen Vollrausch hat er noch nicht, aber angetrunken ist er!"}]'::jsonb, ''),
