  ('mia-geed-da-feidl-im-sock-auf', 'Mia geed da Feidl im Sock auf!', '', '', '', '', 'Mir geht der Feitel im Sack auf', '[{"kategorie": "wörtlich", "text": "\"Mir klappt es das Messer in der Hosentausche auf!\"  2. Das bringt mich auf die Palme!  3. Das bringt mich zur Weißglut!"}]'::jsonb, ''),
