  ('i-hob-scho-wiida-an-samson-ausgfossd', 'I hob scho wiida an Samson ausgfossd!', '', '', '', '', 'Ich habe schon wieder einen Samson ausgefasst!', '[{"kategorie": "", "text": "Ich bin am Wochenende schon wieder zur Arbeit eingeteilt!"}]'::jsonb, ''),
